// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the bytes that would determine immutable args layout when interpreted as calldata
    // We let the fuzzer supply a bytes32 value that we'll place into calldata-derived storage
    // by deploying a fresh clone-like contract is not needed; we only call owner() which reads
    // immutable args via _getArgAddress(offset). The reference contract reads offset 0x00.
    // The property: owner() must equal the address constructed from the first 20 bytes of the
    // 32-byte word at offset 0x00. We supply arbitrary data by encoding it into memory and
    // using a helper contract that mimics the calldata layout through low-level delegatecall.
    // However, owner() is pure and reads via _getImmutableArgsOffset() from calldata, so to
    // exercise it with custom calldata we perform a low-level call to C with crafted calldata.

    // The test fuzzes a 32-byte word 'w' and a padding length 'pad' so that the 2-byte trailer
    // length calculation in _getImmutableArgsOffset can position the immutable args; we keep pad small.
    function testFuzz_property(bytes32 w, uint256 pad) public {
        // keep pad small and reasonable so calldata computations remain valid
        pad = bound(pad, 0, 30);

        // We need to craft calldata so that C.owner() when called on c reads the first immutable arg
        // word at offset 0x00 and returns its high-20 bytes as an address. The clone implementation
        // in reference expects immutable args appended near the end of calldata with a 2-byte length
        // trailer; but owner() uses _getArgAddress(0x0) which computes offset from calldatasize and trailer.
        // We'll directly craft calldata that places our chosen 32-byte word at the computed offset.

        // Build immutable args blob: [ our 32-byte word ][ pad bytes of zeros ]
        bytes memory imm = new bytes(32 + pad);
        assembly { mstore(add(imm,32), w) }
        // trailing pad bytes are already zeros

        // The clone's _getImmutableArgsOffset does:
        // offset := calldatasize() - (shr(240, calldataload(calldatasize()-2)) + 2)
        // So the last two bytes of calldata encode the length of the immutable args plus 2.
        // We'll append a 2-byte trailer value equal to (imm.length + 2)
        uint16 trailer = uint16(imm.length + 2);

        // Build calldata for calling owner(): function selector followed by imm args placed near end and trailer
        bytes memory callData = abi.encodeWithSelector(bytes4(keccak256("owner()")));
        // append imm
        callData = bytes.concat(callData, imm);
        // append trailer as 2 bytes
        bytes memory tr = new bytes(2);
        tr[0] = bytes1(uint8(trailer >> 8));
        tr[1] = bytes1(uint8(trailer));
        callData = bytes.concat(callData, tr);

        // Now perform low-level call to c with crafted calldata. Capture whether it returns and the returned addr.
        (bool ok, bytes memory ret) = address(c).call(callData);
        assertTrue(ok && ret.length == 32);

        // decode returned address from the contract call
        address ownerReturned = abi.decode(ret, (address));

        // Reference semantics: owner() should return the address formed by the high 20 bytes
        // of the first 32-byte word of immutable args (i.e., w >> 96). Compute expected.
        address expected = address(uint160(uint256(w) >> 96));

        // The single assertion: owner() equals expected for all inputs; the mutant that reads at offset 0x04
        // will for some inputs (fuzzer-chosen w/pad) return a different address, causing this assert to fail.
        assertTrue(ownerReturned == expected);
    }
}

