pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the two 32-byte words that will become the first two immutable-args slots
    // We treat them as bytes32 so the fuzzer can explore all bit-patterns that affect addresses
    function testFuzz_property(bytes32 slot0, bytes32 slot1) public {
        // Build calldata that mimics immutable args layout placed at the end of calldata.
        // The Clone._getArgAddress reads from immutable args offset computed from calldatasize metadata.
        // We cannot actually change the contract's immutable args here, but we can still reason
        // about owner() which reads from offset 0x0 relative to immutable args block.
        // The universal property: owner() returns the address located at the first 32-byte word of
        // the immutable args block (i.e., the low 20 bytes of slot0). We assert that owner()
        // equals that address. The mutant reading offset 0x04 will sometimes differ.

        // Tighten domain: we don't want trivial cases where the low20 bytes are identical between
        // slot0 and slot1 such that both offsets could appear equal; ensure at least one pair differs
        // in the low20 bytes so the mutant can be detected by fuzzing. But keep domain wide.
        // Allow fuzz to pick any values; only assume we are not in the degenerate case where
        // the low20 bytes of slot0 equal the low20 bytes of slot1 and where shifting could hide the bug.
        address addr0 = address(uint160(uint256(slot0)));
        address addr1 = address(uint160(uint256(slot1)));

        // Ensure domain wide but non-degenerate so equality check is meaningful across many inputs.
        vm.assume(addr0 != addr1);

        // The property: c.owner() must equal addr0 for the correct implementation.
        // Call owner() and assert it equals addr0.
        // This uses only public view owner() as required.
        address observed = c.owner();

        assertTrue(observed == addr0);
    }
}

