pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameter is the raw bytes that would represent the immutable args block
    function testFuzz_property(bytes memory immArgs) public {
        // We interpret immArgs as the block of immutable args that would be appended to calldata.
        // The reference contract's owner() reads the 20-byte address starting at offset 0x00 of that block;
        // the mutant reads at offset 0x04. We must restrict to cases where immArgs is at least 0x18 (24) bytes
        // so that both 0x00..0x13 (20 bytes) and 0x04..0x17 (20 bytes) are within bounds and owner() calls don't read out-of-range data.
        vm.assume(immArgs.length >= 24);

        // Build a minimal calldata payload that simulates the clone's calldata layout: function selector (owner) has no calldata args,
        // but our Clone._getImmutableArgsOffset uses calldatasize and calldataload of last 2 bytes to find offset. To emulate a realistic appended
        // immutable args block layout as the clone framework does, we craft the calldata as:
        // [selector (4 bytes)] [padding maybe 0..] [immArgs] [2-byte trailer length]
        // The _getImmutableArgsOffset computes offset := calldatasize - ( (calldataload(calldatasize-2) >> 240) + 2 )
        // so we need to put the length of immArgs (as one byte) into the last two bytes such that shr(240, calldataload(size-2)) equals immArgs.length.

        // Prepare selector for owner(): bytes4(keccak256("owner()"))
        bytes4 sel = bytes4(keccak256("owner()"));

        // Build calldata: selector + immArgs + 2-byte trailer containing immArgs.length in the high byte
        bytes memory callData = new bytes(4 + immArgs.length + 2);
        // copy selector
        for (uint256 i = 0; i < 4; i++) callData[i] = sel[i];
        // copy immArgs
        for (uint256 i = 0; i < immArgs.length; i++) callData[4 + i] = immArgs[i];
        // set trailer: high byte = immArgs.length, low byte = 0 (as in clone encoding)
        uint256 trailerIndex = 4 + immArgs.length;
        // immArgs.length must fit in a byte for the shr(240, ...) extraction to match; restrict but keep wide
        vm.assume(immArgs.length <= 255);
        callData[trailerIndex] = bytes1(uint8(immArgs.length));
        callData[trailerIndex + 1] = bytes1(uint8(0));

        // Now perform a low-level call to c.owner() with this calldata so that calldatasize and calldataload behave as intended.
        // We will capture the returned address using try/catch on a staticcall.
        (bool ok, bytes memory ret) = address(c).call(callData);

        // The property we assert: the reference contract returns the address equal to the 20 bytes at immArgs[0..19].
        // We compute that expected address here by taking bytes 0..19 of immArgs.
        // Note: address returned by call may be empty if call reverted; require it succeeded for admissible domain.
        vm.assume(ok && ret.length >= 32);

        // extract address returned by contract
        address returnedAddr = abi.decode(ret, (address));

        // compute expected address from immArgs[0..19]
        bytes20 expected20;
        assembly {
            // load first 32 bytes of immArgs (located at immArgs + 32 in memory)
            let ptr := add(immArgs, 32)
            expected20 := mload(ptr)
        }
        // mask to 20 bytes
        address expected = address(uint160(uint256(expected20)));

        // Single assertion: in the correct contract this always holds for any immArgs (admissible domain),
        // but the mutant reading at offset 0x04 will sometimes differ.
        assertTrue(returnedAddr == expected);
    }
}

