pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // We fuzz a bytes parameter representing an immutable-args block that would be appended by the factory clone.
    // The correct contract reads the address at offset 0x00; the mutant reads at 0x04. For many bytes inputs these
    // produce the same address, but there exist inputs where they differ. We assert that reading owner() (which
    // uses offset 0x00) equals the address we compute by extracting 20 bytes starting at offset 0 of the supplied
    // immutable-data interpreted as calldata slot (big-endian in calldataload): this property holds for the
    // reference implementation for any bytes we supply; the mutant that reads offset 0x04 will differ when the
    // 20-byte words at those offsets differ.
    function testFuzz_property(bytes memory imm) public {
        // Keep domain wide but ensure imm is at least 20 bytes so an address can be formed at offset 0.
        if (imm.length < 20) return;

        // Build a fake calldata layout where the immutable args region starts at offset 0.
        // The Clone._getArgAddress uses calldataload(add(offset, argOffset)) and shr(0x60,..)
        // which effectively takes the 32-byte word at that location and shifts right 96 bits to get low 20 bytes.
        // We can simulate this by taking the 32-byte word starting at imm offset 0.

        // Compute expected address from imm offset 0: read up to 32 bytes starting at imm[0], left-pad to 32 bytes
        bytes32 word0;
        assembly {
            // load first 32 bytes (or partial) of imm into word0
            let data := add(imm, 32)
            word0 := mload(data)
        }
        // According to _getArgAddress, arg := shr(0x60, calldataload(...)) -> takes the high 20 bytes of the 32-byte word
        // shr(0x60) yields the low 20 bytes of the original 32-byte word interpreted as big-endian calldata word.
        // In solidity addresses are the lower 20 bytes of the 32-byte word after shifting right by 96 bits.
        address expected = address(uint160(uint256(word0)));

        // Call owner() on the deployed contract and ensure it equals expected for all inputs.
        // This matches the reference implementation which reads offset 0x00.
        address got = c.owner();

        // Single assertion as required: the reference C returns the address at offset 0x00 (expected)
        assertTrue(got == expected);
    }
}

