pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // We fuzz a bytes parameter representing arbitrary immutable-args calldata block.
    // Admissible domain: any bytes length >= 32 so that reading at offset 0x00 (and 0x04) is defined.
    // General rule: C.owner() returns the address located at immutable offset 0x00 encoded as the high 20 bytes of the 32-byte word at that offset.
    // We implement that decoding and assert equality with c.owner() for all fuzzed bytes with length >= 32.
    function testFuzz_property(bytes memory imm) public {
        // keep domain wide but ensure there's at least one 32-byte word to read at offset 0x00
        vm.assume(imm.length >= 32);

        // compute the expected owner address by reading the first 32-byte word (offset 0x00)
        // owner() uses shr(0x60, calldataload(add(offset, argOffset))) where argOffset==0x0 for reference
        // So decode as the top 20 bytes of imm[0:32]
        bytes32 word;
        assembly {
            word := mload(add(imm, 32))
        }
        // shift right by 0x60 (96) to get low 20 bytes -> we replicate same as shr(0x60, word)
        address expected = address(uint160(uint256(word) >> 96));

        // The contract C.owner() is pure and reads immutable args via _getArgAddress(0x0)
        // But C was deployed without immutable calldata; however owner() is pure and reads from calldatasize() math
        // To simulate calling owner() with the immutable args present, we must call via a low-level call with constructed calldata:
        // owner() selector is 0x8da5cb5b? Actually owner() selector = bytes4(keccak256("owner()"))
        bytes4 sel = bytes4(keccak256("owner()"));

        // Build calldata = function selector || imm
        bytes memory callData = abi.encodePacked(sel, imm);

        // call the contract with that calldata and capture returned address
        (bool ok, bytes memory ret) = address(c).call(callData);
        // owner() is pure and should not revert; but in any case we only consider admissible inputs where call succeeds
        // Keep admissible domain to cases where call does not revert
        vm.assume(ok && ret.length >= 32);

        address got;
        assembly {
            got := mload(add(ret, 32))
        }

        // Single assertion: reference C should return the address encoded at offset 0x00 for ALL admissible imm bytes.
        // The mutant that reads at offset 0x04 will differ for some imm; thus this assertion will fail on the mutant for some fuzz input.
        assertTrue(got == expected);
    }
}

