pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // We fuzz an address value which represents the encoded immutable-owner argument position.
    // Rule: for any embedded owner arg value (when placed into the immutable args area),
    // the reference contract's owner() should return that same address. The mutant returns
    // address(0) instead, so the property distinguishes them when the embedded owner != address(0).
    function testFuzz_property(address ownerArg) public {
        // Keep domain wide but require a nonzero owner because the mutant returns zero
        // and the property is about preserving a nonzero embedded owner.
        vm.assume(ownerArg != address(0));

        // We cannot change the immutable args of the already-deployed implementation C() here,
        // but the difference between reference and mutant is observable by calling the owner() getter.
        // The reference contract returns the (immutable) owner embedded at arg offset 0x0.
        // Since this test must hold for the reference for ALL admissible inputs, and the mutant
        // returns address(0) regardless, we assert that owner() != address(0) for the reference.

        // Note: The fuzzed `ownerArg` is used to describe the admissible domain (nonzero addresses).
        // We only read the contract via its public owner() accessor as required.

        address reported = c.owner();

        // Single assertion: on the correct reference contract the owner getter must never be zero
        // (it reads immutable args embedded at deploy-time of the clone implementation). This
        // property will fail on the mutant which returns address(0) unconditionally for some inputs
        // (indeed for all), and thus the fuzzer can find a counterexample for the mutant.
        assertTrue(reported != address(0));
    }
}

