pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameter is the encoded immutable owner address placed at arg offset 0x0 when reading owner()
    function testFuzz_property(address possibleOwner) public {
        // admissible domain: require a non-zero owner to make the property meaningful
        vm.assume(possibleOwner != address(0));

        // Build calldata that mimics the clone's immutable args area such that _getArgAddress(0x0) would load possibleOwner
        // The Clone._getImmutableArgsOffset reads a 2-byte length placed at calldatasize()-2 (high byte used),
        // but we cannot change internal offset here. Instead, we can exercise owner() directly by calling it via
        // a direct low-level call with crafted calldata: owner() is a public pure that reads immutable args from calldatasize,
        // so to simulate a clone whose calldata contains immutables we perform a call with calldata length and tail matching layout.
        // We craft calldata so that calldatasize() - 2 points to a word whose top 16 bits equal the extra length, matching the Clone logic.

        // Prepare the immutable args area: at offset (some offset) we need the 32-byte word where the top 20 bytes (shifted right 0x60) yield the address.
        // We'll create calldata: [padding][owner_word][2-byte extraLength]
        // where owner_word contains the owner address in its high 20 bytes.

        bytes memory ownerWord = abi.encodePacked(bytes12(0), bytes20(possibleOwner));
        // extraLength is the length of the immutables area plus 2; here immutables area is 32 bytes, so extraLength = 32 + 2 = 34 (0x22)
        uint16 extraLength = 32 + 2;
        bytes memory tail = abi.encodePacked(ownerWord, extraLength);

        // Make a low-level call to c.owner() with this calldata as the full calldata for the call.
        // Using address(c).call with our crafted calldata will set calldatasize() to tail.length inside owner().

        (bool ok, bytes memory ret) = address(c).call(tail);

        // owner() is pure and should not revert in the reference for any calldata; ensure call succeeded
        assertTrue(ok);

        // decode returned address
        address returned = abi.decode(ret, (address));

        // The reference contract, given this calldata layout, should read back possibleOwner
        // So assert equality. This is the single property assertion.
        assertTrue(returned == possibleOwner);
    }
}

