            // store slot0: put addrA at last 20 bytes of first slot
            mstore(add(imm, 32), shl(0x60, addrA))
            // store slot1: addrA (2nd encoded arg)
            mstore(add(imm, 64), shl(0x60, addrA))
            // store slot2: addrB (3rd encoded arg)
