            collAddr = address(col);
        } catch {
            // If collateral() reverts, treat as failure (but reference shouldn't revert)
            collAddr = address(0);
        }

        // We now attempt to call transferFrom on the returned address using a low-level try/catch to capture success
        bool ok;
