                ok = r;
            } catch {
                ok = false;
            }
        } else {
            // If collateral returned something else (including address(0)), attempt call and record whether it succeeded
            try IERC20Minimal(collAddr).transferFrom(address(this), address(1), amount_) returns (bool r) {
                ok = r;
            } catch {
                ok = false;
            }
        }

        // General rule asserted: For the correct contract, collateral() returns a non-zero contract address (the embedded token)
        // such that calling transferFrom on that returned address does NOT always fail; we assert that the call did not fail here.
        // The mutant returning address(0) will make the transferFrom call to address(0) fail for some fuzzed inputs, so the assertion will fail on the mutant.
