import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz the two addresses that would be embedded as immutable args at offsets 0x14 and 0x3c
    // We treat them as arbitrary addresses; the fuzzer will search values that make them differ.
    function testFuzz_property(address addr_at_14, address addr_at_3c) public {
        // Keep wide domain but avoid the trivial case where both addresses equal (then mutant may match reference)
        // We still allow equality but prefer differing values; don't overconstrain.
        // Deploy a clone via ClonesWithImmutableArgs is not required: we only need to observe collateral() on the implementation C
        // The reference contract's collateral() is defined as returning ERC20(_getArgAddress(0x14)).
        // However, because C in this test is the implementation (not a clone with immutables), calling collateral() will
        // read whatever _getImmutableArgsOffset pulls from calldata; to simulate differing immutable args we call the
        // collateral() function via low-level call with crafted calldata where the encoded immutables are placed at
        // the expected end of calldata. We'll construct calldata such that the 0x14 and 0x3c slots contain the two addresses.

        // Build calldata: function selector for collateral() is c.collateral.selector (no args), then append padding and two 32-byte words
        // representing the calldata tail. The Clone._getImmutableArgsOffset computes offset from calldatasize() and reads a length byte
        // at calldatasize()-2 to compute offset; to simulate typical clone layout used in implementation, we must append a 2-byte length
        // and a length prefix word whose high byte equals the extra length. To avoid depending on exact clone layout internals in this unit test,
        // we call collateral() via a calldata layout such that _getArgAddress(0x14) and _getArgAddress(0x3c) read the addresses we embed.

        // Craft calldata manually:
        bytes memory selector = abi.encodePacked(bytes4(keccak256("collateral()")));

        // We will append 4 zero bytes (to align) then two 32-byte words where the first corresponds to offset 0x14 from computed offset
        // and the second to offset 0x3c. To ensure the contract's _getImmutableArgsOffset resolves the offset to the start of these words,
        // we append a fake length encoding used by Clone: final two bytes are: [extraLength (1 byte) , 0x00]. The assembly in Clone:
        // offset := calldatasize() - (shr(240, calldataload(sub(calldatasize(), 2))) + 2)
        // So we store a 32-byte word at calldatasize()-2 whose highest byte (shr(240,...)) equals extraLength.
        // We'll set extraLength to 0x40 (64) so offset = calldatasize() - (64 + 2) = calldatasize() - 66.

        // Build tail: we need at least extraLength bytes after offset. We'll construct layout so that at offset + 0x14 sits addr_at_14,
        // and at offset + 0x3c sits addr_at_3c. Choose extraLength = 0x60 to be safe.

        uint8 extraLength = 0x60;

        // Prepare a bytes buffer: selector + padding to reach some calldatasize then the extra area + 2 final bytes + one word holding extraLength at calldatasize()-2
        // We'll create: calldata = selector (4 bytes) + filler (30 bytes) = 34 bytes so that calldatasize before extras is 34.
        // Then append extraLength bytes of zero (the immutables area), then append 2 bytes (we'll place extraLength as high byte of a 32-byte word whose position is calldatasize()-2)
        // For simpler control, assemble the full calldata in memory.

        bytes memory imm = new bytes(extraLength);
        // Place addr_at_14 at offset 0x14 within imm
        assembly {
            // store addr_at_14 into imm + 0x14
            mstore(add(add(imm, 32), 0x14), shl(0x60, addr_at_14))
            // store addr_at_3c into imm + 0x3c
            mstore(add(add(imm, 32), 0x3c), shl(0x60, addr_at_3c))
        }

        // Build the word that will be at calldatasize()-2: a 32-byte word whose highest byte equals extraLength.
        bytes32 lenWord = bytes32(uint256(uint8(extraLength)) << 248);

        // Assemble final calldata: selector + imm + 2 bytes tail (we will place lenWord at position calldatasize()-2 by appending it so its last two bytes align)
        // Simpler: calldata = selector + padding to make room so that lenWord will start at end-32. We'll append imm, then lenWord, then 2 bytes padding.

        bytes memory data = abi.encodePacked(selector, imm, lenWord);

        // Make the low-level call to c with this calldata and capture return data.
        (bool ok, bytes memory ret) = address(c).call(data);

        // The reference contract should succeed and return the ERC20 address stored at offset 0x14 inside our imm area;
        // we'll decode the returned address and assert equality to addr_at_14. This is the single assertion.

        address returned;
        if (ok && ret.length >= 32) {
            returned = address(uint160(uint256(bytes32(ret))));
        } else {
            // If call reverted or returned unexpected size, mark returned as address(0)
            returned = address(0);
        }

        // The universal property: for any addr_at_14 and addr_at_3c, the correct contract's collateral() returns addr_at_14.
        assertTrue(returned == addr_at_14);
    }
}

